# Moves caboodle, and every other repo on the forge, from "the forge is
# primary" to "GitHub is primary and the forge, builder and cache guests are
# gone". Run it from anywhere; it works on the checkout in $CABOODLE
# (default ~/Projects/personal/caboodle). Each stage checks what's already
# done, so it's safe to stop and re-run, and `github-cutover.sh <n>` starts
# at stage n. Progress is kept in ~/.local/state/caboodle-cutover.

set -E

CHECKOUT="${CABOODLE:-$HOME/Projects/personal/caboodle}"
FORGE_HOST="git.shaneplunkett.com"
FORGE_API="https://$FORGE_HOST/api/v1"
ORG="shane"
GH_OWNER="shaneplunkett"
REPO="$GH_OWNER/caboodle"
CUTOVER_BRANCH="github-cutover"
AI_SKILLS_BRANCH="github-ring-caboodle"
CHECK_RUN="check / check"
ACTIONS_APP_ID=15368
TS_CI_CLIENT="TFs2XEmZQ321CNTRL-krgzEHAvjw11CNTRL"
STATE_DIR="${XDG_STATE_HOME:-$HOME/.local/state}/caboodle-cutover"
RETIRED_HOSTS=(forge builder cache)
OLD_SECRETS=(ATTIC_PULL_TOKEN ATTIC_PUSH_TOKEN HCLOUD_TOKEN TERRAFORM_ACCESS_EMAILS
  TERRAFORM_CLOUDFLARE_TOKEN TERRAFORM_CLOUD_TOKEN TERRAFORM_FORGEJO_TOKEN
  TERRAFORM_HCLOUD_TOKEN TERRAFORM_INCUS_KEY TERRAFORM_UNIFI_TOKEN)
OLD_VARS=(TAILSCALE_CLIENT_ID TAILSCALE_AUDIENCE)
OLD_VAULT=(forgejo-mirror-github forge_token_shane homelab_forgejo_terraform_token
  forge-bot-token forgejo-runner-secret attic-push-token attic-pull-token)
FORGE_TOKEN=""
CHOICE=""
FROM=1

mkdir -p "$STATE_DIR"
touch "$STATE_DIR/done" "$STATE_DIR/accepted"

trap 'warn "stopped in stage $_STAGE_INDEX. Sort out what went wrong above, then pick up there with: github-cutover.sh $_STAGE_INDEX"' ERR

# show "cmd" prints a command the wizard is about to run.
show() { printf '  %s$ %s%s\n' "$DIM" "$1" "$RESET"; }
ok() { printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$1"; }

# Polling reads as: waiting "what"; until <test> || ! tick SECONDS; do :; done
# then the test once more to see which way it ended.
WAITED=0
waiting() {
  WAITED=0
  printf '  %swaiting for %s%s ' "$DIM" "$1" "$RESET"
}

tick() {
  if ((WAITED >= $1)); then
    printf '\n'
    warn "gave up after $(($1 / 60)) minutes"
    return 1
  fi
  sleep 10
  WAITED=$((WAITED + 10))
  printf '.'
}

ready() { printf ' %sdone%s\n' "$GREEN" "$RESET"; }

need_forge() {
  if [[ -z "$FORGE_TOKEN" ]]; then
    rbw unlocked >/dev/null 2>&1 || rbw unlock
    FORGE_TOKEN=$(rbw get forge_token_shane)
  fi
  forge GET /user >/dev/null
}

forge() {
  local method="$1" path="$2"
  shift 2
  curl -fsS --retry 2 -X "$method" -H "Authorization: token $FORGE_TOKEN" \
    -H 'Content-Type: application/json' "$FORGE_API$path" "$@"
}

# forge_pages PATH prints every page of a list endpoint as one JSON array.
forge_pages() {
  local page=1 batch sep='?'
  [[ "$1" == *\?* ]] && sep='&'
  while :; do
    batch=$(forge GET "$1${sep}limit=50&page=$page")
    [[ "$(jq length <<<"$batch")" -eq 0 ]] && break
    printf '%s\n' "$batch"
    page=$((page + 1))
  done | jq -s 'add // []'
}

# forge_pr REPO BRANCH prints the newest pull request from BRANCH, open or not.
forge_pr() {
  forge_pages "/repos/$ORG/$1/pulls?state=all" |
    jq -e --arg b "$2" '[.[] | select(.head.ref == $b)] | sort_by(.number) | last // empty'
}

forge_merge() {
  local repo="$1" number="$2" force="$3" style
  style=$(forge GET "/repos/$ORG/$repo" | jq -r .default_merge_style)
  jq -n --arg style "$style" --argjson force "$force" \
    '{Do: $style, force_merge: $force, delete_branch_after_merge: true}' |
    forge POST "/repos/$ORG/$repo/pulls/$number/merge" --data @- >/dev/null
}

forge_sha() { forge GET "/repos/$ORG/$1/branches/$2" | jq -r .commit.id; }
gh_sha() { gh api "repos/$1/commits/$2" --jq .sha 2>/dev/null || true; }
same_main() { [[ "$(gh_sha "$GH_OWNER/$1" main)" == "$(forge_sha "$1" main)" ]]; }

# refs URL lists a remote's branches and tags as "sha ref", GitHub's through
# gh's login so private repos answer.
refs() {
  git -c credential.helper= -c 'credential.helper=!gh auth git-credential' \
    ls-remote --heads --tags "$1" 2>/dev/null | grep -v '\^{}$' | sort -k2 || true
}

# targets writes "forge-repo github-repo" for every repo on the forge, taking
# the GitHub name from its push mirror while one exists.
targets() {
  local full address
  forge_pages /user/repos | jq -r '.[].full_name' | while read -r full; do
    address=$(forge GET "/repos/$full/push_mirrors" | jq -r '.[0].remote_address // empty')
    if [[ "$address" == https://github.com/* ]]; then
      address=${address#https://github.com/}
      printf '%s %s\n' "$full" "${address%.git}"
    else
      printf '%s %s/%s\n' "$full" "$GH_OWNER" "${full#*/}"
    fi
  done >"$STATE_DIR/targets.new"
  mv "$STATE_DIR/targets.new" "$STATE_DIR/targets"
}

# parity prints one line per forge ref GitHub lacks:
#   missing-repo FORGE GITHUB - -
#   missing|diverged FORGE GITHUB REF SHA
# A ref counts as kept when GitHub has it at the same commit under its own
# name or under forge/<name>, or when it was accepted as a loss.
parity() {
  local full target sha ref kept
  while read -r full target; do
    if ! gh repo view "$target" --json name >/dev/null 2>&1; then
      printf 'missing-repo %s %s - -\n' "$full" "$target"
      continue
    fi
    local -A on_github=()
    while read -r sha ref; do
      [[ -n "$sha" ]] && on_github[$ref]=$sha
    done < <(refs "https://github.com/$target.git")
    while read -r sha ref; do
      [[ -n "$sha" ]] || continue
      grep -qxF "$full $ref" "$STATE_DIR/accepted" && continue
      [[ "${on_github[$ref]:-}" == "$sha" ]] && continue
      kept=${ref/refs\/heads\//refs/heads/forge/}
      kept=${kept/refs\/tags\//refs/tags/forge/}
      [[ "${on_github[$kept]:-}" == "$sha" ]] && continue
      if [[ -z "${on_github[$ref]:-}" ]]; then
        printf 'missing %s %s %s %s\n' "$full" "$target" "$ref" "$sha"
      else
        printf 'diverged %s %s %s %s\n' "$full" "$target" "$ref" "$sha"
      fi
    done < <(refs "ssh://forgejo@forge/$full.git")
    unset on_github
  done <"$STATE_DIR/targets"
}

# fix_gaps FILE pushes what each problem line lacks from a fresh clone of the
# forge repo: a missing ref under its own name, a diverged one under
# forge/<name> so GitHub's stays, and a missing repo whole into a new private
# repo. Nothing on GitHub is overwritten.
fix_gaps() {
  local file="$1" full target kind ref sha tmp log
  local -a specs repos
  mapfile -t repos < <(awk '{print $2}' "$file" | sort -u)
  for full in "${repos[@]}"; do
    target=$(awk -v f="$full" '$2 == f {print $3; exit}' "$file")
    tmp=$(mktemp -d)
    log="$tmp/push.log"
    git clone -q --mirror "ssh://forgejo@forge/$full.git" "$tmp/repo.git"
    specs=()
    while read -r kind _ _ ref sha; do
      case "$kind" in
        missing-repo)
          gh repo create "$target" --private >/dev/null
          specs=('refs/heads/*:refs/heads/*' 'refs/tags/*:refs/tags/*')
          break
          ;;
        missing) specs+=("$sha:$ref") ;;
        diverged)
          ref=${ref/refs\/heads\//refs/heads/forge/}
          specs+=("$sha:${ref/refs\/tags\//refs/tags/forge/}")
          ;;
      esac
    done < <(awk -v f="$full" '$2 == f' "$file")
    if git -C "$tmp/repo.git" -c credential.helper= -c 'credential.helper=!gh auth git-credential' \
      push "https://github.com/$target.git" "${specs[@]}" >"$log" 2>&1; then
      ok "$target: pushed ${#specs[@]} ref(s)"
    else
      warn "$target: push failed"
      sed 's/^/      /' "$log" | tail -8
      if grep -q GH007 "$log"; then
        say "GitHub refused a commit carrying your private email (GH007)."
        step "On github.com/settings/emails, untick 'Block command line pushes that expose my email', then recheck here to push again."
        step "Tick it again once the push goes through."
      fi
    fi
    rm -rf "$tmp"
  done
}

# parity_gate loops until every forge ref is on GitHub or accepted.
parity_gate() {
  local problems
  need_forge
  say "Comparing every branch and tag on the forge with GitHub (about a minute)..."
  targets
  while :; do
    problems=$(mktemp)
    parity >"$problems"
    if [[ ! -s "$problems" ]]; then
      ok "GitHub has every branch and tag the forge has, in all $(wc -l <"$STATE_DIR/targets") repos"
      rm -f "$problems"
      return
    fi
    warn "GitHub is missing these:"
    awk '{ if ($1 == "missing-repo") printf "      %s: no repo %s on GitHub\n", $2, $3; else printf "      %s: %s %s (%.7s)\n", $2, $1, $4, $5 }' "$problems"
    note "missing: GitHub has no such ref. diverged: GitHub's points somewhere else."
    say "Fixing pushes missing refs under their own name and diverged ones as forge/<name>, so nothing on GitHub is overwritten."
    ask CHOICE "[f]ix by pushing, [a]ccept these as lost, [r]echeck, [q]uit:"
    case "$CHOICE" in
      f*) fix_gaps "$problems" ;;
      a*)
        warn "The accepted refs will only exist in the forge's archive (stage 24)."
        if confirm "Accept every ref listed above as not moving to GitHub?"; then
          awk '$1 != "missing-repo" {print $2, $4}' "$problems" >>"$STATE_DIR/accepted"
          awk '$1 == "missing-repo" {print $2}' "$problems" | while read -r full; do
            refs "ssh://forgejo@forge/$full.git" | awk -v f="$full" '{print f, $2}' >>"$STATE_DIR/accepted"
          done
        fi
        ;;
      q*)
        rm -f "$problems"
        return 1
        ;;
    esac
    rm -f "$problems"
  done
}

tf() {
  local token
  token=$(cd "$CHECKOUT/modules/agenix" && ../../scripts/in-dev-shell.sh agenix -d terraform-cloud-token.age)
  (
    cd "$CHECKOUT/terraform"
    export TF_TOKEN_app_terraform_io="$token"
    ../scripts/in-dev-shell.sh terraform init -input=false -no-color >/dev/null
    ../scripts/in-dev-shell.sh terraform "$@"
  )
}

pull_main() {
  git -C "$CHECKOUT" fetch -q origin
  git -C "$CHECKOUT" merge -q --ff-only origin/main
}

tailnet_has() {
  tailscale status --json 2>/dev/null | jq -e --arg n "$1" \
    '[.Peer[]? | select(.DNSName | startswith($n + "."))] | length > 0' >/dev/null
}

lan_ip() { (cd "$CHECKOUT" && scripts/quietly.sh nix eval --raw ".#network.devices.$1.ip"); }

# switch_by_hand HOST ADDRESS is the PVE doc's recipe: build here, copy the
# closure over SSH, switch.
switch_by_hand() {
  local host="$1" address="$2" path remote
  path=$(cd "$CHECKOUT" && scripts/quietly.sh nix build --no-link --print-out-paths ".#hydraJobs.$host")
  nix copy --to "ssh://root@$address" "$path"
  printf -v remote 'nix-env -p /nix/var/nix/profiles/system --set %q && %q/bin/switch-to-configuration switch' "$path" "$path"
  ssh "root@$address" bash -s <<<"$remote"
}

no_attic() {
  local substituters
  substituters=$("$@" nix config show substituters 2>/dev/null) || return 1
  [[ "$substituters" != *cache.shaneplunkett.com* ]]
}

# ── Stages ────────────────────────────────────────────────────────────────

s_preflight() {
  stage "Before anything changes"
  say "Nothing changes in this stage. It checks the tools, logins and machines the rest needs."
  local tool missing=0
  for tool in gh rbw jq curl git ssh fish nix; do
    command -v "$tool" >/dev/null 2>&1 || {
      warn "$tool isn't on PATH"
      missing=1
    }
  done
  command -v tailscale >/dev/null 2>&1 || note "tailscale isn't on PATH, so the tailnet checks will be yours to eyeball."
  ((missing == 0)) || return 1
  gh auth status >/dev/null 2>&1 || {
    warn "gh isn't signed in: gh auth login"
    return 1
  }
  ok "gh is signed in"
  need_forge
  ok "the forge answers with your token"
  [[ -d "$CHECKOUT/.git" ]] || {
    warn "no caboodle checkout at $CHECKOUT; set CABOODLE to yours"
    return 1
  }
  if [[ "$(git -C "$CHECKOUT" branch --show-current)" != main || -n "$(git -C "$CHECKOUT" status --porcelain)" ]]; then
    warn "$CHECKOUT needs to be on main with nothing uncommitted, since Terraform and the deploys run from it."
    return 1
  fi
  ok "$CHECKOUT is on a clean main"
  local host
  for host in pve builder mirror; do
    if ssh -o BatchMode=yes -o ConnectTimeout=5 "root@$host" true 2>/dev/null; then
      ok "root@$host answers"
    else
      warn "root@$host doesn't answer over SSH"
      return 1
    fi
  done
  local cutover ai
  cutover=$(forge_pr caboodle "$CUTOVER_BRANCH") || {
    warn "no cutover pull request from $CUTOVER_BRANCH on the forge"
    return 1
  }
  ai=$(forge_pr ai-skills "$AI_SKILLS_BRANCH") || {
    warn "no ai-skills pull request from $AI_SKILLS_BRANCH on the forge"
    return 1
  }
  ok "caboodle #$(jq .number <<<"$cutover") ($(jq -r .state <<<"$cutover")) and ai-skills #$(jq .number <<<"$ai") ($(jq -r .state <<<"$ai")) are the two pull requests this merges"
  note "Pick up at any stage later with: github-cutover.sh <stage>"
}

s_parity() {
  stage "GitHub has every branch and tag the forge has"
  say "Before anything stops or goes, every branch and tag in every forge repo should be on GitHub."
  say "The push mirrors do most of it; this finds what they missed."
  parity_gate
}

s_freeze() {
  stage "Quiet the forge"
  say "Stops forge-bot's Renovate and the forge's runner on the builder, so nothing else merges on the forge."
  say "The cutover pull request removes the forge's own check, so nothing needs the runner now."
  show "ssh root@builder systemctl stop renovate.timer renovate.service"
  show "ssh root@builder systemctl stop --no-block forgejo-runner-builder.service"
  if confirm "Stop them?"; then
    ssh root@builder systemctl stop renovate.timer renovate.service
    ssh root@builder systemctl stop --no-block forgejo-runner-builder.service
    ok "stopped (the runner lets a running job finish first)"
  fi
  need_forge
  say "Open pull requests on the forge, which won't merge there now:"
  local full
  forge_pages /user/repos | jq -r '.[] | select(.open_pr_counter > 0) | .full_name' | while read -r full; do
    forge GET "/repos/$full/pulls?state=open&limit=50" |
      jq -r --arg r "$full" '.[] | "      \($r)#\(.number) \(.title) (\(.user.login))"'
  done
  note "Their branches are on GitHub already, so anything of yours can be reopened there."
  note "forge-bot's Renovate updates come back on their own from GitHub's Renovate."
  pause "Enter once nothing above needs merging on the forge first"
}

s_github_settings() {
  stage "Let GitHub auto-merge"
  say "Renovate's pull requests and the ai-skills bump merge themselves, which needs auto-merge on the repo."
  say "Deleting merged branches keeps the branch list from filling with them."
  local current
  current=$(gh api "repos/$REPO" --jq '"\(.allow_auto_merge) \(.delete_branch_on_merge)"')
  if [[ "$current" == "true true" ]]; then
    ok "already on"
    return
  fi
  show "gh api -X PATCH repos/$REPO -F allow_auto_merge=true -F delete_branch_on_merge=true"
  if confirm "Turn them on?"; then
    gh api -X PATCH "repos/$REPO" -F allow_auto_merge=true -F delete_branch_on_merge=true >/dev/null
    ok "on"
  fi
}

s_tf_forget_forge() {
  stage "Terraform forgets the forge's settings"
  say "terraform/forge-config.tf manages Forgejo through its provider. The cutover deletes both, and the"
  say "forge won't be there to answer, so Terraform drops those resources from its state now, while"
  say "main still has the provider. Nothing on the forge changes."
  local -a doomed
  mapfile -t doomed < <(tf state list | grep -E '^(data\.)?forgejo_' || true)
  if ((${#doomed[@]} == 0)); then
    ok "Terraform's state has nothing of the forge's left"
    return
  fi
  printf '      %s\n' "${doomed[@]}"
  show "terraform state rm <the ${#doomed[@]} above>"
  if confirm "Remove them from the state?"; then
    tf state rm "${doomed[@]}"
    ok "forgotten"
  fi
}

s_merge_cutover() {
  stage "Merge the cutover on the forge"
  need_forge
  local pr number head sha tmp started finished
  pr=$(forge_pr caboodle "$CUTOVER_BRANCH")
  number=$(jq .number <<<"$pr")
  if [[ "$(jq -r .merged <<<"$pr")" == true ]]; then
    ok "#$number is already merged"
  else
    head=$(jq -r .head.sha <<<"$pr")
    say "#$number is the last caboodle merge on the forge. It deletes the forge's own check, so the"
    say "required one can never report and the merge has to be forced. The same gate runs here first,"
    say "on the pull request's head ($head)."
    show "scripts/check.sh   (in a throwaway worktree of the head)"
    tmp=$(mktemp -d)
    git -C "$CHECKOUT" fetch -q origin "refs/pull/$number/head"
    git -C "$CHECKOUT" worktree add -q --detach "$tmp/head" "$head"
    if ! (cd "$tmp/head" && scripts/in-dev-shell.sh scripts/check.sh); then
      git -C "$CHECKOUT" worktree remove --force "$tmp/head"
      warn "the gate failed on #$number, so it doesn't merge"
      return 1
    fi
    git -C "$CHECKOUT" worktree remove --force "$tmp/head"
    ok "the gate passes on #$number"
    confirm "Merge #$number on the forge now, past the required check?" || return 1
    forge_merge caboodle "$number" true
    ok "merged"
  fi
  say "Pushing it to GitHub through the push mirror..."
  forge POST "/repos/$ORG/caboodle/push_mirrors-sync" >/dev/null 2>&1 || true
  waiting "GitHub's main to match the forge's"
  until same_main caboodle || ! tick 300; do :; done
  same_main caboodle
  ready
  pull_main
  sha=$(gh_sha "$REPO" main)
  check_done() {
    [[ "$(gh api "repos/$REPO/commits/$sha/check-runs" --jq "[.check_runs[] | select(.name == \"$CHECK_RUN\")][0].status" 2>/dev/null)" == completed ]]
  }
  say "This is the first run of the check without Attic, so it compiles colmena and friends."
  waiting "the check on GitHub's main"
  until check_done || ! tick 2400; do :; done
  check_done
  ready
  read -r conclusion started finished < <(gh api "repos/$REPO/commits/$sha/check-runs" \
    --jq "[.check_runs[] | select(.name == \"$CHECK_RUN\")][0] | \"\(.conclusion) \(.started_at) \(.completed_at)\"")
  if [[ "$conclusion" == success ]]; then
    ok "the check passed on GitHub in $((($(date -d "$finished" +%s) - $(date -d "$started" +%s)) / 60)) minutes"
  else
    warn "the check came back $conclusion: https://github.com/$REPO/actions/workflows/check.yml"
    say "Fix it with a pull request on GitHub once stage 8 has run; the rest doesn't depend on it."
    confirm "Carry on?" || return 1
  fi
}

s_caboodle_mirror_off() {
  stage "Stop caboodle's push mirror"
  need_forge
  say "The push mirror runs git push --mirror, which deletes any GitHub branch the forge lacks, so it"
  say "has to stop before anything happens on GitHub's side."
  waiting "GitHub's main to match the forge's"
  until same_main caboodle || ! tick 120; do :; done
  same_main caboodle
  ready
  local name
  for name in $(forge GET "/repos/$ORG/caboodle/push_mirrors" | jq -r '.[].remote_name'); do
    show "DELETE /repos/$ORG/caboodle/push_mirrors/$name"
    if confirm "Delete caboodle's push mirror $name?"; then
      forge DELETE "/repos/$ORG/caboodle/push_mirrors/$name" >/dev/null
      ok "deleted"
    fi
  done
  if [[ "$(forge GET "/repos/$ORG/caboodle/push_mirrors" | jq length)" -eq 0 ]]; then ok "caboodle has no push mirror"; fi
  say "The mirror also copied forge-bot's branches. Renovate on GitHub would treat its renovate/ ones as"
  say "someone else's edits and skip them, so they go:"
  local -a stale
  mapfile -t stale < <(
    gh api "repos/$REPO/git/matching-refs/heads/renovate/" --jq '.[].ref' 2>/dev/null
    gh api "repos/$REPO/git/matching-refs/heads/update/" --jq '.[].ref' 2>/dev/null
  )
  if ((${#stale[@]} == 0)); then
    ok "none left"
    return
  fi
  printf '      %s\n' "${stale[@]#refs/heads/}"
  if confirm "Delete these ${#stale[@]} branches on GitHub?"; then
    for name in "${stale[@]}"; do
      gh api -X DELETE "repos/$REPO/git/${name}" >/dev/null
    done
    ok "deleted"
  fi
}

s_ruleset() {
  stage "Require the check on GitHub's main"
  say "A ruleset on main that requires $CHECK_RUN and nothing else: no review, no up-to-date rule."
  say "It waits until now because it would have refused the push mirror's pushes."
  local id body
  body=$(jq -n --arg check "$CHECK_RUN" --argjson app "$ACTIONS_APP_ID" '{
    name: "main", target: "branch", enforcement: "active",
    conditions: { ref_name: { include: ["~DEFAULT_BRANCH"], exclude: [] } },
    rules: [{ type: "required_status_checks", parameters: {
      strict_required_status_checks_policy: false,
      do_not_enforce_on_create: false,
      required_status_checks: [{ context: $check, integration_id: $app }] } }] }')
  id=$(gh api "repos/$REPO/rulesets" --jq '.[] | select(.name == "main") | .id')
  if [[ -n "$id" ]]; then
    show "gh api -X PUT repos/$REPO/rulesets/$id   (the ruleset above)"
    if confirm "Update the existing main ruleset to match?"; then
      gh api -X PUT "repos/$REPO/rulesets/$id" --input - <<<"$body" >/dev/null
    fi
  else
    show "gh api -X POST repos/$REPO/rulesets   (the ruleset above)"
    if confirm "Create it?"; then
      gh api -X POST "repos/$REPO/rulesets" --input - <<<"$body" >/dev/null
    fi
  fi
  if [[ "$(gh api "repos/$REPO/rules/branches/main" --jq '[.[] | select(.type == "required_status_checks") | .parameters | "\(.strict_required_status_checks_policy) \(.required_status_checks | map(.context) | join(","))"] | join(";")')" == "false $CHECK_RUN" ]]; then
    ok "main requires $CHECK_RUN only, with no up-to-date rule"
  else
    warn "main's rules don't read as expected"
  fi
  open_url "https://github.com/$REPO/settings/rules"
  step "The page lists one ruleset, 'main', Active, targeting the default branch."
  step "Inside it, only 'Require status checks to pass' is ticked, with '$CHECK_RUN' and 'Require branches to be up to date' unticked."
  pause "Enter once it reads that way"
  say "Renovate's force block and renovate-github/ prefix went with the cutover:"
  if gh api "repos/$REPO/contents/.github/workflows/renovate.yml" --jq .content | base64 -d | grep -qE 'force|renovate-github'; then
    warn "GitHub's renovate.yml still has them; the cutover didn't land as expected"
  else
    ok "gone from GitHub's main"
  fi
}

s_ai_skills() {
  stage "Move the ai-skills bump to GitHub"
  need_forge
  say "ai-skills' new workflow mints an App token to dispatch caboodle, so that repo needs the App's secrets."
  local have pr number since sha run
  have=$(gh secret list --repo "$GH_OWNER/ai-skills" --json name --jq '[.[].name] | join(" ")')
  if [[ " $have " == *" APP_CLIENT_ID "* && " $have " == *" APP_PRIVATE_KEY "* ]]; then
    ok "ai-skills already has APP_CLIENT_ID and APP_PRIVATE_KEY"
  else
    show "rbw get github-app-client-id | gh secret set APP_CLIENT_ID --repo $GH_OWNER/ai-skills"
    show "rbw get github-app-private-key | base64 -d | gh secret set APP_PRIVATE_KEY --repo $GH_OWNER/ai-skills"
    if confirm "Set them from Bitwarden?"; then
      rbw get github-app-client-id | gh secret set APP_CLIENT_ID --repo "$GH_OWNER/ai-skills"
      rbw get github-app-private-key | base64 -d | gh secret set APP_PRIVATE_KEY --repo "$GH_OWNER/ai-skills"
      WRITTEN_SECRET+=("ai-skills/APP_CLIENT_ID" "ai-skills/APP_PRIVATE_KEY")
    fi
  fi
  pr=$(forge_pr ai-skills "$AI_SKILLS_BRANCH")
  number=$(jq .number <<<"$pr")
  since=$(date -u +%Y-%m-%dT%H:%M:%SZ)
  if [[ "$(jq -r .merged <<<"$pr")" == true ]]; then
    ok "ai-skills #$number is already merged"
  else
    say "ai-skills #$number swaps the forge workflow for the GitHub one. It's the last merge on the forge."
    confirm "Merge ai-skills #$number on the forge?" || return 1
    forge_merge ai-skills "$number" false || {
      warn "the forge refused a plain merge"
      confirm "Force it past the forge's checks?" || return 1
      forge_merge ai-skills "$number" true
    }
    ok "merged"
  fi
  forge POST "/repos/$ORG/ai-skills/push_mirrors-sync" >/dev/null 2>&1 || true
  waiting "GitHub's ai-skills main to match the forge's"
  until same_main ai-skills || ! tick 300; do :; done
  same_main ai-skills
  ready
  sha=$(gh_sha "$GH_OWNER/ai-skills" main)
  say "That push should go all the way round: ai-skills' ring-caboodle run, caboodle's ai-skills.yml,"
  say "and a pull request from the App that merges itself once $CHECK_RUN passes."
  ring_done() {
    [[ "$(gh run list --repo "$GH_OWNER/ai-skills" --workflow ring-caboodle.yml --commit "$sha" --json status --jq '.[0].status' 2>/dev/null)" == completed ]]
  }
  waiting "ai-skills' ring-caboodle run"
  until ring_done || ! tick 300; do :; done
  if ring_done; then
    ready
    run=$(gh run list --repo "$GH_OWNER/ai-skills" --workflow ring-caboodle.yml --commit "$sha" --json conclusion,url --jq '.[0] | "\(.conclusion) \(.url)"')
    note "ring-caboodle: $run"
  fi
  bump_done() {
    [[ "$(gh run list --repo "$REPO" --workflow ai-skills.yml --created ">=$since" --json status --jq '.[0].status' 2>/dev/null)" == completed ]]
  }
  waiting "caboodle's ai-skills.yml run"
  until bump_done || ! tick 1200; do :; done
  if bump_done; then
    ready
    note "ai-skills.yml: $(gh run list --repo "$REPO" --workflow ai-skills.yml --created ">=$since" --json conclusion,url --jq '.[0] | "\(.conclusion) \(.url)"')"
  fi
  pr=$(gh pr list --repo "$REPO" --head update/ai-skills --state all --limit 1 --json number,state,url,autoMergeRequest,author \
    --jq '.[0] | "#\(.number) \(.state) by \(.author.login), auto-merge \(if .autoMergeRequest then "on" else "off" end): \(.url)"')
  if [[ -n "$pr" ]]; then
    note "the bump: $pr"
    open_url "$(awk '{print $NF}' <<<"$pr")"
    step "The pull request's author is the App, '$CHECK_RUN' runs on it, and it says it will merge automatically (or has)."
  else
    warn "no update/ai-skills pull request on GitHub yet; the runs above say why"
  fi
  pause "Enter once the bump looks right, or you've noted what to fix"
}

s_dump() {
  stage "Save the forge's issues and pull requests"
  need_forge
  say "tools/forgejo-dump.sh saves every repo's issues, pull requests, comments and reviews as JSON,"
  say "and they go in the mirror's folder, where restic keeps them. Both merges are in, so this is final."
  local tmp
  tmp=$(mktemp -d)
  show "tools/forgejo-dump.sh $tmp/forgejo"
  show "tar -C $tmp -cf - forgejo | ssh root@mirror '... /var/lib/mirror/forgejo'"
  if confirm "Take the dump?"; then
    "$CHECKOUT/tools/forgejo-dump.sh" "$tmp/forgejo"
    tar -C "$tmp" -cf - forgejo | ssh root@mirror \
      'rm -rf /var/lib/mirror/forgejo && tar -C /var/lib/mirror -xf - && chown -R mirror:mirror /var/lib/mirror/forgejo'
    ok "on the mirror: $(ssh root@mirror 'du -sh /var/lib/mirror/forgejo | cut -f1; find /var/lib/mirror/forgejo -type f | wc -l' | paste -sd' ') files"
  fi
  rm -rf "$tmp"
}

s_mirrors_off() {
  stage "Stop every push mirror"
  need_forge
  say "One last sync of every repo's mirror, the same branch-and-tag check as stage 2, then the mirrors go."
  local full name count=0
  targets
  while read -r full _; do
    forge POST "/repos/$full/push_mirrors-sync" >/dev/null 2>&1 || true
  done <"$STATE_DIR/targets"
  note "syncs asked for; giving them a minute"
  sleep 60
  parity_gate
  local -a with_mirrors=()
  while read -r full _; do
    if [[ "$(forge GET "/repos/$full/push_mirrors" | jq length)" -gt 0 ]]; then with_mirrors+=("$full"); fi
  done <"$STATE_DIR/targets"
  if ((${#with_mirrors[@]} == 0)); then
    ok "no push mirrors left"
    return
  fi
  say "${#with_mirrors[@]} repos still push to GitHub: ${with_mirrors[*]}"
  confirm "Delete all their push mirrors?" || return 1
  for full in "${with_mirrors[@]}"; do
    for name in $(forge GET "/repos/$full/push_mirrors" | jq -r '.[].remote_name'); do
      forge DELETE "/repos/$full/push_mirrors/$name" >/dev/null && count=$((count + 1))
    done
  done
  ok "deleted $count push mirrors"
}

s_token() {
  stage "Delete the forjgo token"
  say "The push mirrors signed in to GitHub with a fine-grained token you named 'forjgo token'."
  say "Nothing uses it now. GitHub has no API for deleting your own token, so this one is yours."
  open_url "https://github.com/settings/personal-access-tokens"
  step "Under Fine-grained tokens, click 'forjgo token'."
  step "Scroll to the bottom and click Delete, then confirm in the dialog."
  pause "Enter once it's deleted"
  local token code
  if ! token=$(rbw get forgejo-mirror-github 2>/dev/null); then
    note "forgejo-mirror-github isn't in Bitwarden, so check the token's gone from the list yourself."
    return 0
  fi
  code=$(curl -s -o /dev/null -w '%{http_code}' -H "Authorization: Bearer $token" https://api.github.com/user || true)
  if [[ "$code" == 401 ]]; then
    ok "GitHub refuses the token now (401)"
  else
    warn "GitHub still answers the token ($code), so it isn't deleted yet"
  fi
}

s_actions_cleanup() {
  stage "Clear the old pipeline's Actions secrets"
  say "These only served October's pipeline (Attic, Terraform in CI, the tailnet join)."
  say "APP_CLIENT_ID, APP_PRIVATE_KEY and INPUTS_TOKEN stay."
  local name
  local -a secrets vars envs
  mapfile -t secrets < <(gh api "repos/$REPO/actions/secrets" --jq '.secrets[].name' | grep -xF -f <(printf '%s\n' "${OLD_SECRETS[@]}") || true)
  mapfile -t vars < <(gh api "repos/$REPO/actions/variables" --jq '.variables[].name' | grep -xF -f <(printf '%s\n' "${OLD_VARS[@]}") || true)
  mapfile -t envs < <(gh api "repos/$REPO/environments" --jq '.environments[].name' 2>/dev/null || true)
  if ((${#secrets[@]} + ${#vars[@]} + ${#envs[@]} == 0)); then
    ok "nothing left to clear"
  else
    ((${#secrets[@]})) && say "secrets: ${secrets[*]}"
    ((${#vars[@]})) && say "variables: ${vars[*]}"
    ((${#envs[@]})) && say "environments: ${envs[*]}"
    if confirm "Delete them?"; then
      for name in "${secrets[@]}"; do gh secret delete "$name" --repo "$REPO"; done
      for name in "${vars[@]}"; do gh variable delete "$name" --repo "$REPO"; done
      for name in "${envs[@]}"; do gh api -X DELETE "repos/$REPO/environments/$name"; done
      ok "cleared"
    fi
  fi
  note "left: $(gh api "repos/$REPO/actions/secrets" --jq '[.secrets[].name] | join(", ")')"
}

