s_checkouts() {
  stage "Point your checkouts at GitHub"
  say "Every checkout under ~/Projects whose origin is the forge switches to GitHub. A 'github' remote"
  say "pointing at the same repo goes, since origin is it now. The T3 worktrees share caboodle's remotes."
  local dir url name target github
  local -a plan=()
  for dir in "$HOME"/Projects/*/*/ "$CHECKOUT/"; do
    [[ -d "$dir/.git" ]] || continue
    url=$(git -C "$dir" remote get-url origin 2>/dev/null || true)
    [[ "$url" == *forgejo@forge* || "$url" == *"$FORGE_HOST"* ]] || continue
    name=${url%.git}
    name=${name##*/}
    target=$(awk -v f="$ORG/$name" '$1 == f {print $2}' "$STATE_DIR/targets" 2>/dev/null || true)
    target=${target:-$GH_OWNER/$name}
    plan+=("${dir%/} $target")
  done
  mapfile -t plan < <(printf '%s\n' "${plan[@]}" | sort -u | sed '/^$/d')
  if ((${#plan[@]} == 0)); then
    ok "no checkout still points at the forge"
  else
    local line
    for line in "${plan[@]}"; do
      read -r dir target <<<"$line"
      if gh repo view "$target" --json name >/dev/null 2>&1; then
        say "${dir/#"$HOME"/'~'} → git@github.com:$target.git"
      else
        warn "${dir/#"$HOME"/'~'}: no $target on GitHub, so it's left alone"
      fi
    done
    if confirm "Repoint these?"; then
      for line in "${plan[@]}"; do
        read -r dir target <<<"$line"
        gh repo view "$target" --json name >/dev/null 2>&1 || continue
        git -C "$dir" remote set-url origin "git@github.com:$target.git"
        github=$(git -C "$dir" remote get-url github 2>/dev/null || true)
        [[ "${github%.git}" == "git@github.com:$target" ]] && git -C "$dir" remote remove github
        git -C "$dir" fetch -q --prune origin || warn "${dir/#"$HOME"/'~'}: fetch failed"
      done
      ok "repointed"
    fi
  fi
  pull_main
  ok "caboodle's main is GitHub's: $(git -C "$CHECKOUT" log -1 --format='%h %s')"
  say "The MacBook's and the mini's checkouts need the same, on each:"
  show "git remote set-url origin git@github.com:$GH_OWNER/<repo>.git"
  pause
}

s_terraform_apply() {
  stage "Terraform removes the guests"
  say "The forge's container stays, stopped, for the last stage to archive or delete once the mirror"
  say "has a fresh copy, so Terraform forgets it rather than destroying it. Its R2 bucket keeps its"
  say "backups the same way: Terraform can't delete a bucket that has objects in it."
  show "ssh root@pve 'incus stop forge; incus config set forge boot.autostart=false'"
  if confirm "Stop the forge for good?"; then
    ssh root@pve 'incus stop forge 2>/dev/null; incus config set forge boot.autostart=false'
    ok "stopped, and it won't start with PVE"
  fi
  local -a forget=()
  local address listed
  listed=$(tf state list)
  for address in 'incus_instance.guest["forge"]' 'cloudflare_r2_bucket.backup["forge"]'; do
    if grep -qxF "$address" <<<"$listed"; then forget+=("$address"); fi
  done
  if ((${#forget[@]})); then
    show "terraform state rm ${forget[*]}"
    if confirm "Forget them?"; then tf state rm "${forget[@]}"; fi
  fi
  say "The plan, from GitHub's main:"
  (cd "$CHECKOUT" && scripts/terraform.sh) | grep -E '^  # |^Plan:|^No changes' || true
  note "Expect 9 to destroy and nothing else: the builder's and the cache's containers, the three UniFi"
  note "reservations, the cache's generated MAC, and the forge's Storage Box subaccount, its password and"
  note "its R2 token. Deleting the subaccount leaves its folder on the box."
  ask CHOICE "Type apply to apply it (it plans again and applies that plan), anything else to skip:"
  if [[ "$CHOICE" == apply ]]; then
    (cd "$CHECKOUT" && scripts/terraform.sh apply)
    ok "applied"
  else
    _skip "Terraform apply" "scripts/terraform.sh apply"
  fi
  ssh root@pve incus list -c ns -f csv | grep -E '^(forge|builder|cache),' | sed 's/^/      /' || true
}

