s_loose_ends() {
  stage "Loose ends outside this repo"
  say "None of these block anything, but they still say the forge:"
  step "ai-skills: the pr and forgejo-tea skills say the forge is origin, and ai-skills has no GitHub check (its check.yml was a forge workflow)."
  step "shaneplunkett/workflows: .forgejo/ and default.json's forgejo-tags manager point at the forge."
  step "workflows' check.yml only adds extra caches with an Attic endpoint. Adding them always would take terraform and agenix from numtide's cache and leave only colmena compiling, which halves the check."
  step "Linear (Settings, Integrations, GitHub) and anything else linking pull requests should list $REPO."
  step "Vex Code read tea's forge login; tea went with the cutover."
  pause "Enter to carry on"
}

s_vault() {
  stage "Tidy Bitwarden and local leftovers"
  say "Bitwarden entries that only served the forge, the builder or Attic. Each is asked about on its own."
  local entry
  for entry in "${OLD_VAULT[@]}"; do
    rbw get "$entry" >/dev/null 2>&1 || continue
    if confirm "Remove $entry from Bitwarden?"; then
      rbw remove "$entry"
      ok "removed $entry"
    fi
  done
  if [[ -d "$HOME/.config/tea" ]]; then
    say "tea's config in $HOME/.config/tea still holds the forge token it wrote there."
    if confirm "Delete ~/.config/tea?"; then
      rm -rf "$HOME/.config/tea"
      ok "deleted"
    fi
  fi
}

s_forge_data() {
  stage "Archive or delete the forge's data"
  say "First the mirror fetches everything again, and each GitHub repo's branches and tags are compared"
  say "with its bare clone. Only then does the stopped forge container on PVE get archived or deleted."
  show "ssh root@mirror systemctl start mirror"
  ssh root@mirror systemctl start mirror || true
  local result name gh_refs mirror_refs remote fresh=0 differ=0
  result=$(ssh root@mirror systemctl show mirror -p Result --value)
  if [[ "$result" == success ]]; then
    ok "the mirror's run succeeded"
  else
    warn "the mirror's run ended $result: ssh root@mirror journalctl -u mirror"
  fi
  for name in $(gh repo list "$GH_OWNER" --limit 500 --json name --jq '.[].name'); do
    gh_refs=$(refs "https://github.com/$GH_OWNER/$name.git")
    printf -v remote "git -C %q for-each-ref --format='%%(objectname)	%%(refname)' refs/heads refs/tags 2>/dev/null" "/var/lib/mirror/$name.git"
    mirror_refs=$(ssh root@mirror bash -s <<<"$remote" | sort -k2 || true)
    if [[ "$gh_refs" == "$mirror_refs" ]]; then
      fresh=$((fresh + 1))
    else
      differ=$((differ + 1))
      warn "$name: the mirror's copy differs from GitHub"
    fi
  done
  say "$fresh repos match GitHub exactly, $differ don't."
  if [[ -s "$STATE_DIR/accepted" ]]; then
    warn "$(wc -l <"$STATE_DIR/accepted") refs you accepted in stage 2 only exist in the forge."
  fi
  confirm "Does the mirror hold a fresh copy of everything you want kept?" || {
    _skip "the forge's data" "github-cutover.sh 24 once the mirror is fresh"
    return
  }
  local archive
  archive="/mnt/user/archive/forge-$(date +%F).tar.gz"
  say "a: export the container to $archive on PVE's pool, then delete it"
  say "d: delete it outright"
  say "k: keep it stopped for now"
  ask CHOICE "a, d or k:"
  case "$CHOICE" in
    a*)
      printf -v remote 'mkdir -p /mnt/user/archive && incus export forge %q --instance-only && ls -lh %q && incus delete forge' "$archive" "$archive"
      show "ssh root@pve '$remote'"
      ssh root@pve bash -s <<<"$remote"
      ok "archived and deleted"
      ;;
    d*)
      if confirm "Delete the forge container and everything in it, with no copy?"; then
        ssh root@pve incus delete forge
        ok "deleted"
      fi
      ;;
    *) note "kept; it's stopped and won't start with PVE" ;;
  esac
}

s_tidy_pr() {
  stage "Retire this wizard"
  say "Its job's done. Removing it is a pull request on GitHub, which also proves the everyday path:"
  say "gh files it, $CHECK_RUN runs, and main requires it."
  if [[ ! -e "$CHECKOUT/scripts/github-cutover.sh" ]]; then
    ok "already gone from main"
    return
  fi
  show "git switch -c retire-cutover-wizard origin/main; git rm scripts/github-cutover.sh; git commit; git push"
  show "gh pr create --assignee $GH_OWNER"
  confirm "Open it?" || return 0
  (
    cd "$CHECKOUT"
    git switch -q -c retire-cutover-wizard origin/main
    git rm -q scripts/github-cutover.sh
    git commit -q -m "remove the GitHub cutover wizard now the cutover is done"
    git push -q -u origin retire-cutover-wizard
    gh pr create --repo "$REPO" --assignee "$GH_OWNER" \
      --title "remove the GitHub cutover wizard now the cutover is done" \
      --body "The cutover ran, so its wizard has nothing left to do."
    git switch -q main
  )
}

# want N says whether stage N runs this time, and counts it past otherwise.
want() {
  if (($1 >= FROM)); then
    return 0
  fi
  _STAGE_INDEX=$1
  return 1
}

finished() {
  grep -qx "$1" "$STATE_DIR/done" || printf '%s\n' "$1" >>"$STATE_DIR/done"
  pause "Enter for the next stage"
}

run_wizard() {

  TOTAL_STAGES=25
  FROM="${1:-$(($(sort -n "$STATE_DIR/done" | tail -n1) + 1))}"

  banner "GitHub cutover: GitHub primary, forge, builder and cache gone"
  if ((FROM > 1 && FROM <= TOTAL_STAGES)); then
    note "Picking up at stage $FROM. Pass a number to start somewhere else."
    pause
  fi

  if want 1; then
    s_preflight
    finished 1
  fi
  if want 2; then
    s_parity
    finished 2
  fi
  if want 3; then
    s_freeze
    finished 3
  fi
  if want 4; then
    s_github_settings
    finished 4
  fi
  if want 5; then
    s_tf_forget_forge
    finished 5
  fi
  if want 6; then
    s_merge_cutover
    finished 6
  fi
  if want 7; then
    s_caboodle_mirror_off
    finished 7
  fi
  if want 8; then
    s_ruleset
    finished 8
  fi
  if want 9; then
    s_ai_skills
    finished 9
  fi
  if want 10; then
    s_dump
    finished 10
  fi
  if want 11; then
    s_mirrors_off
    finished 11
  fi
  if want 12; then
    s_token
    finished 12
  fi
  if want 13; then
    s_actions_cleanup
    finished 13
  fi
  if want 14; then
    s_tailscale_ci
    finished 14
  fi
  if want 15; then
    s_checkouts
    finished 15
  fi
  if want 16; then
    s_terraform_apply
    finished 16
  fi
  if want 17; then
    s_deploy_servers
    finished 17
  fi
  if want 18; then
    s_switch_hypervisors
    finished 18
  fi
  if want 19; then
    s_switch_workstations
    finished 19
  fi
  if want 20; then
    s_tailscale_machines
    finished 20
  fi
  if want 21; then
    s_pocket_id
    finished 21
  fi
  if want 22; then
    s_loose_ends
    finished 22
  fi
  if want 23; then
    s_vault
    finished 23
  fi
  if want 24; then
    s_forge_data
    finished 24
  fi
  if want 25; then
    s_tidy_pr
    finished 25
  fi

  finish
}

run_wizard "$@"
exit
